import sys, json
from collections import deque
input_data = sys.stdin.read().strip()
grid = json.loads(input_data)

def numIslands(grid):
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    count = 0

    def bfs(r, c):
        queue = deque([(r, c)])
        grid[r][c] = '0'
        while queue:
            cr, cc = queue.popleft()
            for dr, dc in [(1,0),(-1,0),(0,1),(0,-1)]:
                nr, nc = cr+dr, cc+dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '1':
                    grid[nr][nc] = '0'
                    queue.append((nr, nc))

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '1':
                count += 1
                bfs(r, c)
    return count

print(numIslands(grid))

import java.util.*;
public class Solution {
    static char[][] grid;
    static int rows, cols;
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String line = sc.nextLine().trim();
        // Parse 2D array
        line = line.substring(1, line.length()-1); // remove outer []
        List<char[]> gridList = new ArrayList<>();
        int i = 0;
        while (i < line.length()) {
            if (line.charAt(i) == '[') {
                int j = line.indexOf(']', i);
                String row = line.substring(i+1, j);
                String[] cells = row.split(",");
                char[] r = new char[cells.length];
                for (int c = 0; c < cells.length; c++) r[c] = cells[c].trim().charAt(1);
                gridList.add(r);
                i = j + 1;
            } else i++;
        }
        grid = gridList.toArray(new char[0][]);
        rows = grid.length; cols = grid[0].length;
        int count = 0;
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                if (grid[r][c] == '1') { count++; dfs(r, c); }
        System.out.println(count);
    }
    static void dfs(int r, int c) {
        if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] == '0') return;
        grid[r][c] = '0';
        dfs(r+1,c); dfs(r-1,c); dfs(r,c+1); dfs(r,c-1);
    }
}

