    vector<string> rowStrs;
    int depth = 0; string cur;
    for (char ch : line) {
        if (ch=='[') { depth++; if(depth==2) cur=""; }
        else if (ch==']') { depth--; if(depth==1) rowStrs.push_back(cur); }
